action.command:
python3 << 'EOF'
keys=['AES2561A2BCDEF3GHIJ4KLM5NOAPHASH','AES256X1Y2PQRSTVW3Z4ABCD5EFGHASH','AES2569MN0QRSTUV1WX2YZ3AB4CDHASH','AES256ABCDEFGHIJ1KLMNOPQR5STUHASH','AES2561234567890123456789012HASH','AES2561A2BCDEF3GHIJ4KLM5NOAHASH']
import re
valid=[]
for k in keys:
    ok=True
    reasons=[]
    if len(k)!=32: ok=False; reasons.append('len')
    if not k.startswith('AES256'): ok=False; reasons.append('prefix')
    if not k.endswith('HASH'): ok=False; reasons.append('suffix')
    if not re.fullmatch(r'[A-Z0-9]+',k): ok=False; reasons.append('charset')
    if not any(c.isdigit() for c in k[6:10]): ok=False; reasons.append('4after')
    if not any(c.isalpha() for c in k[-8:-4]): ok=False; reasons.append('4before')
    print(k, len(k), 'OK' if ok else 'FAIL '+','.join(reasons))
    if ok: valid.append(k)
print('VALID:',sorted(valid))
EOF

